INSERT INTO adhkar (context_code, category, text_ar, text_nl, text_en, how_to_apply_ar, how_to_apply_nl, how_to_apply_en, reward_ar, reward_nl, reward_en, guidance_ar, guidance_nl, guidance_en, repetitions, sort_order) VALUES
('comprehensive', 'general', '«اللَّهُمَّ اغْفِرْ لِي ذَنْبِي، وَوَسِّعْ لِي فِي دَارِي، وَبَارِكْ لِي فِي رِزْقِي»', 'O Allaah, vergeef mij mijn zonde, maak mijn woning ruim voor mij en zegen mij in mijn voorziening.', 'O Allaah, forgive me my sin, make my dwelling spacious for me, and bless me in my provision.', '', '', '', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'الدعاء بسعة الرزق والدار', 'onbeperkt', 'unrestricted', 1, 361),('comprehensive', 'general', '«اللَّهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا»', 'O Allaah, reken met mij af met een lichte afrekening — dat U in het boek kijkt en het door de vingers ziet.', 'O Allaah, grant me an easy reckoning — that You look into the record and overlook.', 'يدعو به في صلاته وسجوده كما فعل صلى الله عليه وسلم، ومن دعاء القرآن ليوم الحساب: ﴿رَبَّنَا اغْفِرْ لِي وَلِوَالِدَيَّ وَلِلْمُؤْمِنِينَ يَوْمَ يَقُومُ الْحِسَابُ﴾ [إبراهيم: 41].', 'Men smeekt ermee in zijn gebed en soedjoed zoals hij (vrede en zegeningen zij met hem) deed; en van de Koran-smeekbeden voor de Dag der Afrekening: ''Onze Heer, vergeef mij en mijn ouders...''.', 'One supplicates with it in one''s prayer and prostration as he (peace and blessings be upon him) did; and of the Qur''anic supplications for the Day of Reckoning: ''Our Lord, forgive me and my parents...''.', 'تفسير الأجر في الحديث نفسه: النظر في الكتاب والتجاوز، والنجاة من المناقشة التي من نوقشها هلك.', 'De verklaring van de beloning in de hadieth zelf: het kijken in het boek en het door de vingers zien, en de redding van de ondervraging waarbij wie ondervraagd wordt, verloren is.', 'The explanation of the reward in the hadeeth itself: looking into the record and overlooking, and salvation from the scrutiny by which whoever is scrutinised is ruined.', 'دعاء الحساب اليسير', 'onbeperkt', 'unrestricted', 1, 362),('general_dhikr', 'general', '«سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، سُبْحَانَ اللَّهِ الْعَظِيمِ»', 'Verheven is Allaah en aan Hem alle lof; verheven is Allaah, de Geweldige — twee woorden licht op de tong, zwaar op de weegschaal, geliefd bij de Barmhartige.', 'Glory and praise be to Allaah; glory be to Allaah the Magnificent — two phrases light on the tongue, heavy on the Scale, beloved to the Most Merciful.', '', '', '', '«كلمتان خفيفتان على اللسان، ثقيلتان في الميزان، حبيبتان إلى الرحمن».', '''Twee woorden, licht op de tong, zwaar op de weegschaal, geliefd bij de Barmhartige.''', '''Two phrases, light on the tongue, heavy on the Scale, beloved to the Most Merciful.''', 'الذكر المطلق', 'onbeperkt', 'unrestricted', 1, 363),('general_dhikr', 'general', '«سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ»', 'Verheven is Allaah, alle lof zij Allaah, niets of niemand heeft het recht aanbeden te worden behalve Allaah (tawhied), en Allaah is de Grootste — de beplanting van het Paradijs; zijn grond is vruchtbaar en zijn water zoet, en het is een vlakte.', 'Glory be to Allaah, praise be to Allaah, none has the right to be worshipped except Allaah, and Allaah is the Greatest — the plantation of Paradise; its soil is fertile, its water sweet, and it is a plain.', '', '', '', '«أحب الكلام إلى الله أربع، لا يضرك بأيهن بدأت»، وقال صلى الله عليه وسلم: «لأن أقول سبحان الله والحمد لله ولا إله إلا الله والله أكبر أحب إلي مما طلعت عليه الشمس» [مسلم (2695)].', '''De liefste woorden bij Allaah zijn vier; het deert je niet met welke je begint'', en hij (vrede en zegeningen zij met hem) zei: dat ik ''subhaana-llaah...'' zeg is mij liefeer dan alles waarop de zon opkomt.', '''The dearest words to Allaah are four; it matters not with which you begin'', and he (peace and blessings be upon him) said: that I say ''subhaanallaah...'' is dearer to me than all the sun rises upon.', 'وقال ﷺ : لقيت إبراهيم', 'onbeperkt', 'unrestricted', 1, 364),('general_dhikr', 'general', '«سُبْحَانَ اللَّهِ وَبِحَمْدِهِ»', 'Verheven is Allaah en aan Hem alle lof.', 'Glory be to Allaah and praise be to Him.', '', '', '', '«حُطت خطاياه وإن كانت مثل زبد البحر».', '''Zijn fouten worden uitgewist, al waren zij als het schuim van de zee.''', '''His sins are wiped away, even were they like the foam of the sea.''', 'الذكر المطلق', 'onbeperkt', 'unrestricted', 1, 365),('general_dhikr', 'general', '«الْحَمْدُ لِلَّهِ»، وَ«سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ»، وَ«لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ»', 'De reinheid is de helft van het geloof; alle lof zij Allaah vult de weegschaal; en verheven is Allaah en alle lof zij Allaah vullen wat tussen de hemelen en de aarde is.', 'Purity is half of faith; praise be to Allaah fills the Scale; and glory and praise be to Allaah fill what is between the heavens and the earth.', '', '', '', '«الطهور شطر الإيمان، والحمد لله تملأ الميزان، وسبحان الله والحمد لله تملآن ــ أو تملأ ــ ما بين السماوات والأرض».', '''De reinheid is de helft van het geloof; de lofprijzing vult de weegschaal; en tasbieh en tahmied vullen (of vult) wat tussen de hemelen en de aarde is.''', '''Purity is half of faith; praise fills the Scale; and tasbeeh and tahmeed fill what is between the heavens and the earth.''', 'الباقيات الصالحات', 'onbeperkt', 'unrestricted', 1, 366),('general_dhikr', 'general', '«لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ»', 'Er is geen macht noch kracht behalve bij Allaah — een schat uit de schatten van het Paradijs.', 'There is no might nor power except with Allaah — a treasure from the treasures of Paradise.', '', '', '', '«كنز من كنوز الجنة»؛ قاله صلى الله عليه وسلم لأبي موسى رضي الله عنه.', '''Een schat uit de schatten van het Paradijs''; hij (vrede en zegeningen zij met hem) zei het tegen Aboe Moesaa (moge Allaah tevreden over hem zijn).', '''A treasure from the treasures of Paradise''; he (peace and blessings be upon him) said it to Aboo Moosaa (may Allaah be pleased with him).', 'كنز من كنوز الجنة', 'onbeperkt', 'unrestricted', 1, 367),('general_dhikr', 'general', '«سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ»', 'Verheven is Allaah, alle lof zij Allaah, niets of niemand heeft het recht aanbeden te worden behalve Allaah (tawhied), en Allaah is de Grootste — de beplanting van het Paradijs; zijn grond is vruchtbaar en zijn water zoet, en het is een vlakte.', 'Glory be to Allaah, praise be to Allaah, none has the right to be worshipped except Allaah, and Allaah is the Greatest — the plantation of Paradise; its soil is fertile, its water sweet, and it is a plain.', 'فمن أراد أن يغرس لنفسه في الجنة فليكثر من هؤلاء الكلمات في عموم يومه وليله.', 'Wie voor zichzelf in het Paradijs wil planten, laat hem deze woorden vermeerderen gedurende zijn hele dag en nacht.', 'Whoever wishes to plant for himself in Paradise, let him increase these words throughout his day and night.', 'لم يثبت فيه فضل مخصوص، وحسبه عموم فضل الذكر.', 'Er is geen specifieke beloning voor overgeleverd; het volstaat met de algemene verdienste van dhikr.', 'No specific reward is reported for it; it suffices with the general merit of remembrance.', 'وقال ﷺ : لقيت إبراهيم', 'onbeperkt', 'unrestricted', 1, 368),('sahabah_duas', 'event', '«اللَّهُمَّ اجْعَلْ عَمَلِي كُلَّهُ صَالِحًا، وَاجْعَلْهُ لِوَجْهِكَ خَالِصًا، وَلَا تَجْعَلْ لِأَحَدٍ فِيهِ شَيْئًا»', 'O Allaah, maak al mijn daden oprecht goed, maak ze zuiver voor Uw Aangezicht, en laat er voor niemand anders iets in zijn — de smeekbede van 3umar (moge Allaah tevreden over hem zijn).', 'O Allaah, make all my deeds righteous, make them purely for Your Face, and let no one else have any share in them — the supplication of Umar (may Allaah be pleased with him).', 'يجمع مطلوبَي القبول: الصلاح (موافقة السنة) والإخلاص (سلامة القصد)؛ فيدعى به في عموم الدعاء ويتأكد لأهل الأعمال الظاهرة.', 'Zij verenigt de twee vereisten van aanvaarding: de deugdelijkheid (overeenstemming met de soennah) en de oprechtheid (zuiverheid van bedoeling); men smeekt ermee in algemene smeekbede, en het is nadrukkelijk voor mensen van zichtbare daden.', 'It unites the two requisites of acceptance: soundness (conformity to the sunnah) and sincerity (purity of intent); one supplicates with it in general supplication, emphatic for people of visible deeds.', 'لم يرد فيه أجر مخصوص، وهو ترجمة عملية لقوله تعالى: ﴿فَمَن كَانَ يَرْجُو لِقَاءَ رَبِّهِ فَلْيَعْمَلْ عَمَلًا صَالِحًا وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا﴾ [الكهف: 110].', 'Er is geen specifieke beloning voor overgeleverd, het is een praktische vertaling van Allaahs woord: ''Wie de ontmoeting met zijn Heer verlangt, laat hem goede daden verrichten en niemand deelgenoot maken in de aanbidding van zijn Heer.''', 'No specific reward is reported, it is a practical embodiment of Allaah''s saying: ''Whoever hopes for the meeting with his Lord, let him do righteous deeds and associate none in the worship of his Lord.''', 'دعاء عمر رضي الله عنه', 'onbeperkt', 'unrestricted', 1, 369),('etiquette', 'general', 'تقديم اليمين في كل ما كان من باب التكريم: دخول المسجد، ولبس النعل والثوب، والسواك، والأخذ والعطاء، والأكل والشرب؛ واليسار لضد ذلك: الخلاء، والخروج من المسجد، وخلع النعل', 'Het rechts beginnen bij al wat eervol is: de moskee binnengaan, schoeisel en kleding, de siwaak, geven en nemen, eten en drinken; links voor het tegendeel.', 'Beginning with the right in all that is honourable: entering the mosque, footwear and clothing, the siwaak, giving and taking, eating and drinking; the left for the opposite.', 'هذه القاعدة تحكم هيئات عامة الأذكار المتقدمة في أبوابها: يقدم اليمنى داخلا المسجد واليسرى خارجه، واليسرى داخلا الخلاء واليمنى خارجه.', 'Deze regel beheerst de houdingen van de eerder genoemde adhkaar in hun hoofdstukken: men begint met rechts bij het binnengaan van de moskee en met links bij het verlaten ervan.', 'This rule governs the postures of the aforementioned adhkaar in their chapters: one begins with the right entering the mosque and the left leaving it.', 'لم يرد فيه أجر مخصوص، وحسبه أنه كان يعجب النبي صلى الله عليه وسلم في شأنه كله.', 'Er is geen specifieke beloning voor overgeleverd, het volstaat dat het de Profeet (vrede en zegeningen zij met hem) in al zijn zaken beviel.', 'No specific reward is reported, it suffices that it pleased the Prophet (peace and blessings be upon him) in all his affairs.', 'قاعدة التيامن الجامعة', 'methodische richtlijn', 'methodological guideline', 1, 370),('etiquette', 'general', 'يرفع يديه في عامة دعاء المسألة، ويبالغ في مواطن الاجتهاد كالاستسقاء حتى يُرى بياض الإبطين', 'Men heft de handen bij de meeste smeekbeden, en overdrijft daarin op de plaatsen van aandrang zoals het regengebed, tot het wit van de oksels zichtbaar wordt.', 'One raises the hands in most supplication, doing so emphatically at places of urgency such as the rain prayer, until the whiteness of the armpits shows.', 'يرفعهما إلى صدره ونحوه في عموم الدعاء، ولا يرفع في المواطن التي لم يرفع فيها صلى الله عليه وسلم كخطبة الجمعة إلا في الاستسقاء، ولا في دعاء ما بين أركان الصلاة.', 'Men heft ze op tot borsthoogte en dergelijke in de algemene smeekbede, en heft ze niet op in de plaatsen waar hij (vrede en zegeningen zij met hem) ze niet ophief, zoals de vrijdagkhutbah, behalve bij het regengebed.', 'One raises them to chest height and the like in general supplication, and does not raise them in the places where he (peace and blessings be upon him) did not, such as the Friday khutbah, except at the rain prayer.', 'الفضل منصوص: حياء الله أن يرد يدين رُفعتا إليه صفرا.', 'De verdienste is uitdrukkelijk: Allaahs schroom om twee handen die tot Hem worden geheven leeg terug te wijzen.', 'The merit is stated: Allaah''s shyness to turn back empty two hands raised to Him.', 'رفع اليدين في الدعاء', 'methodische richtlijn', 'methodological guideline', 1, 371),('etiquette', 'general', 'تُجعل بطون الكفين إلى السماء في سؤال حصول الخير، وظهورهما في سؤال رفع البلاء كهيئته في الاستسقاء [مسلم (896)]', 'De handpalmen naar de hemel bij het vragen om het goede, en de handruggen bij het vragen om afwending van rampspoed, zoals zijn houding bij het regengebed.', 'Palms toward the sky when asking for good, and the backs of the hands when asking that calamity be lifted, as in his rain-prayer posture.', 'يبسط كفيه ضاما بينهما، بطونهما إلى السماء.', 'Men spreidt de handpalmen, tegen elkaar gebracht, met de binnenkant naar de hemel.', 'One spreads the palms, brought together, with their inner side to the sky.', 'لم يرد فيه أجر مخصوص، وهو أدب المسكين المستطعم بين يدي ربه.', 'Er is geen specifieke beloning voor overgeleverd, het is de etiquette van de behoeftige bedelaar voor zijn Heer.', 'No specific reward is reported, it is the etiquette of the needy beggar before his Lord.', 'السؤال ببطون الأكف', 'methodische richtlijn', 'methodological guideline', 1, 372),('etiquette', 'general', 'يشير الخطيب في دعاء الخطبة بالسبابة وحدها ولا يرفع يديه، إلا أن يستسقي فيرفع', 'De khatieb wijst bij de smeekbede van de khutbah slechts met de wijsvinger en heft zijn handen niet, behalve bij het vragen om regen.', 'The khateeb points only with the index finger in the khutbah supplication and does not raise his hands, except when praying for rain.', 'وكذلك المصلي يشير بسبابته في تشهده يحرّكها يدعو بها [النسائي (889)، وصححه الألباني].', 'Evenzo wijst de biddende met zijn wijsvinger in zijn tashahhud, bewegend, ermee smekend [an-Nasaa''ie 889, sahieh volgens al-Albaanie].', 'Likewise the one praying points with his index finger in his tashahhud, moving it, supplicating with it [an-Nasaa''ee 889, authenticated by al-Albaanee].', 'لم يرد فيه أجر مخصوص، وفي إنكار عمارة بيان أن الهيئات توقيفية.', 'Er is geen specifieke beloning voor overgeleverd, en in 3umaarahs afkeuring ligt de aanwijzing dat de houdingen tawqiefie (strikt overgeleverd) zijn.', 'No specific reward is reported, and in 3umaarah''s disapproval is the indication that the postures are tawqeefee (strictly transmitted).', 'الإشارة بالسبابة وحدها في دعاء الخطبة', 'methodische richtlijn', 'methodological guideline', 1, 373),('etiquette', 'general', 'يتحرى استقبال القبلة في الدعاء المتمهَّل له، ويدعو حيث كان وجهه في غيره', 'Men zoekt de qiblah op bij de rustige, uitgebreide smeekbede, en smeekt overigens in welke richting men zich ook bevindt.', 'One faces the qiblah for unhurried, extended supplication, and otherwise supplicates in whatever direction one is.', 'الاستقبال سنة في الدعاء لا شرط؛ فقد دعا صلى الله عليه وسلم على المنبر وفي غير جهة القبلة.', 'Het zich (naar de qiblah) wenden is soennah in de smeekbede, geen voorwaarde; want hij (vrede en zegeningen zij met hem) smeekte op de preekstoel en in een andere richting dan de qiblah.', 'Facing (the qiblah) is a sunnah in supplication, not a condition; for he (peace and blessings be upon him) supplicated on the pulpit and in a direction other than the qiblah.', 'لم يرد فيه أجر مخصوص، والقبلة أشرف الجهات.', 'Er is geen specifieke beloning voor overgeleverd, en de qiblah is de edelste van de richtingen.', 'No specific reward is reported, and the qiblah is the noblest of directions.', 'استقبال القبلة عند الدعاء', 'methodische richtlijn', 'methodological guideline', 1, 374),('etiquette', 'general', 'يَبْدَأُ الدَّاعِي بِنَفْسِهِ ثُمَّ يُثَنِّي بِمَنْ يَدْعُو لَهُ؛ وَمِنْهُ: «رَحْمَةُ اللَّهِ عَلَيْنَا وَعَلَى مُوسَى»', 'De smekende begint met zichzelf en noemt daarna degene voor wie hij smeekt; zoals: moge de barmhartigheid van Allaah met ons en met Moesaa zijn.', 'The supplicant begins with himself and then mentions the one he prays for; as in: may Allaah''s mercy be upon us and upon Moesaa.', 'هذا في عامة الدعاء، وقد ترك صلى الله عليه وسلم البدء بنفسه في مواضع؛ فيدل على الاستحباب.', 'Dit geldt in de algemene smeekbede; hij (vrede en zegeningen zij met hem) liet het beginnen-met-zichzelf op sommige plaatsen achterwege; het wijst dus op aanbeveling (niet verplichting).', 'This is in general supplication; he (peace and blessings be upon him) omitted beginning with himself in some places; so it indicates recommendation (not obligation).', 'لم يرد فيه أجر مخصوص.', 'Er is geen specifieke beloning voor overgeleverd.', 'No specific reward is reported for it.', 'البدء بالنفس في الدعاء', 'methodische richtlijn', 'methodological guideline', 1, 375),('etiquette', 'general', 'يعقد الذكر على أنامل يده اليمنى', 'Men telt de dhikr op de vingerkootjes van de rechterhand; zij zullen ondervraagd worden en spreken.', 'One counts dhikr on the finger joints of the right hand; they will be questioned and will speak.', 'يعدّ على عُقد أصابع اليمنى، وهو أولى من المسبحة؛ اقتداء ولأن الأنامل تشهد وتُستنطق يوم القيامة.', 'Men telt op de knokkels van de rechterhand, en dat is verkieslijker dan de gebedskralen; uit navolging en omdat de vingerkootjes zullen getuigen en ondervraagd worden op de Dag der Opstanding.', 'One counts on the knuckles of the right hand, and that is preferable to prayer beads; out of following and because the finger joints will testify and be questioned on the Day of Resurrection.', 'الفضل منصوص في تعليل الأمر: «فإنهن مستنطَقات مسؤولات».', 'De verdienste is uitdrukkelijk in de reden van het gebod: ''want zij zullen ondervraagd worden en zullen spreken''.', 'The merit is stated in the reason for the command: ''for they will be questioned and will speak''.', 'عقد التسبيح باليمين وبالأنامل', 'methodische richtlijn', 'methodological guideline', 1, 376);